#include <bits/stdc++.h>
using namespace std;

int N, fifty, hundred, K;
int memo[2][51][51];
int memo2[2][51][51][101];
const int MOD = 1000000007;
long long comb[101][101];

int solve(int t, int f, int h) {
    if (f == 0 && h == 0)
        return 0;
    if (memo[t][f][h] != -1)
        return memo[t][f][h];
    if (t == 1)
        return memo[t][f][h] = 1 + (f < 50 ? solve(0, f + 1, h) : solve(0, f, h + 1));
    int ans = 1000000;
    for (int i = 0; i <= f; i++) {
        if (i * 50 > K)
            break;
        int j = std::min((K - i * 50) / 100, h);
        int totalW = i * 50 + j * 100;
        if ((50 - f + i > 0 && totalW > 50) || (100 - h + j > 1 && totalW > 100) || (i == 50 && j == 50))
            continue;
        ans = std::min(ans, solve(1, f - i, h - j));
    }
    return memo[t][f][h] = ans + 1;
}

int solve2(int t, int f, int h, int r) {
    if (r == 0 && f == 0 && h == 0)
        return 1;
    if (r == 0)
        return 0;
    if (memo2[t][f][h][r] != -1)
        return memo2[t][f][h][r];
    long long ans = 0;
    if (t == 1) {
        for (int i = 0; i <= 50 - f; ++i) {
            if (i * 50 > K)
                break;
            for (int j = 0; j <= 50 - h; ++j) {
                if (i == 0 && j == 0)
                    continue;
                int totalW = i * 50 + j * 100;
                if (totalW > K)
                    break;
                long long temp = (comb[50 - f][i] * comb[50 - h][j]) % MOD;
                temp = (temp * solve2(0, f + i, h + j, r - 1)) % MOD;
                ans = (ans + temp) % MOD;
            }
        }
    } else {
        for (int i = 0; i <= f; ++i) {
            if (i * 50 > K)
                break;
            for (int j = 0; j <= h; ++j) {
                if (i == 0 && j == 0)
                    continue;
                int totalW = i * 50 + j * 100;
                if (totalW > K)
                    break;
                long long temp = (comb[f][i] * comb[h][j]) % MOD;
                temp = (temp * solve2(1, f - i, h - j, r - 1)) % MOD;
                ans = (ans + temp) % MOD;
            }
        }
    }
    return memo2[t][f][h][r] = (int)ans;
}

long long nCk(int n, int k) {
    if (n < k)
        return 0;
    if (k == 0 || k == n)
        return 1;
    if (comb[n][k] != -1)
        return comb[n][k];
    if (n - k < k)
        return comb[n][k] = nCk(n, n - k);
    return comb[n][k] = ((long long)n * nCk(n - 1, k - 1) % MOD) * pow_mod(k, MOD - 2) % MOD;
}

long long pow_mod(long long x, long long p) {
    long long result = 1;
    long long base = x % MOD;
    while (p > 0) {
        if (p & 1)
            result = (result * base) % MOD;
        base = (base * base) % MOD;
        p >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> K;
    vector<int> arr(N);
    for (int i = 0; i < N; i++)
        cin >> arr[i];
    for (int val : arr) {
        if (val == 50)
            fifty++;
        else if (val == 100)
            hundred++;
    }
    for (int i = 0; i < 2; i++)
        for (int j = 0; j <= fifty; j++)
            for (int j2 = 0; j2 <= hundred; j2++)
                for (int j3 = 0; j3 <= 100; j3++)
                    memo2[i][j][j2][j3] = -1;
    for (int i = 0; i <= 100; i++)
        for (int j = 0; j <= 100; j++)
            comb[i][j] = -1;
    int minVal = solve(0, fifty, hundred);
    if (minVal >= 1000000) {
        cout << -1 << "\n" << 0 << "\n";
        return 0;
    }
    int maxR = minVal;
    int res = 0;
    for (int r = 1; r <= maxR; r++) {
        res = (res + solve2(0, fifty, hundred, r)) % MOD;
    }
    cout << minVal << "\n" << res << "\n";
    return 0;
}
